{
  "claims": [
    {
      "anchor": "ANALYZE gathers the statistics the query planner relies on",
      "claim_text": "ANALYZE gathers the statistics the query planner relies on.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S0", "rel": "entails"},
        {"sid": "P0.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P0.S0 says planner relies on statistics; P0.S1 says ANALYZE gathers them."
    },
    {
      "anchor": "it can run on its own or as an optional step in VACUUM",
      "claim_text": "ANALYZE can be invoked by itself or as an optional step in VACUUM.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Direct restatement of P0.S1."
    },
    {
      "anchor": "ANALYZE samples rows randomly instead of reading every row",
      "claim_text": "ANALYZE uses a statistically random sampling of rows rather than reading every row.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Direct restatement of P4.S2."
    },
    {
      "anchor": "it is usually best to just analyze the whole database",
      "claim_text": "It is usually best to just analyze the entire database.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Direct restatement of P4.S1."
    },
    {
      "anchor": "by default it samples 30,000 rows per table",
      "claim_text": "By default ANALYZE samples 30,000 rows per table.",
      "kind": "direct",
      "sure": true,
      "evidence": [],
      "check": null,
      "reasoning": "No passage mentions a default sample size of 30,000 rows."
    },
    {
      "anchor": "The autovacuum daemon schedules ANALYZE purely as a function of the number of rows inserted or updated",
      "claim_text": "The autovacuum daemon schedules ANALYZE strictly as a function of the number of rows inserted or updated.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Direct restatement of P1.S2."
    },
    {
      "anchor": "it may skip a table whose statistical distribution changed meaningfully if only a few rows were touched",
      "claim_text": "Autovacuum may skip a table whose statistical distribution changed meaningfully if only a few rows were touched.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P1.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P1.S2 says daemon has no knowledge of meaningful statistical changes and schedules by row count."
    },
    {
      "anchor": "Changes to partitions or inheritance children do not trigger autoanalyze on the parent table",
      "claim_text": "Changes to partitions or inheritance children do not trigger autoanalyze on the parent table.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S0", "rel": "entails"},
        {"sid": "P6.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S0 and P6.S1 both state this."
    },
    {
      "anchor": "an inheritance parent is never analyzed by autovacuum",
      "claim_text": "An inheritance parent is never analyzed by autovacuum.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P6.S1", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "P6.S1 says parent is analyzed if the parent itself is changed, so 'never' is too strong."
    },
    {
      "anchor": "autovacuum runs ANALYZE on a partitioned table only after its partitions change significantly",
      "claim_text": "Autovacuum runs ANALYZE on a partitioned table only after its partitions change significantly.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P6.S0", "rel": "refutes"},
        {"sid": "P7.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "P6.S0 and P7.S2 say autovacuum does not issue ANALYZE on partitioned tables at all."
    },
    {
      "anchor": "A timestamp column that records each row's update time will probably need more frequent statistics updates than a column of URLs",
      "claim_text": "A timestamp column that records each row's update time will probably need more frequent statistics updates than a column of URLs.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P3.S3", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P3.S3 states this comparison directly."
    }
  ]
}
